input.command:
cat > tests/deliver_test.sh <<'EOF'
#!/bin/bash
# deliver: a succeeding command is delivered on the first attempt; a failing one exits 1.
fail=0
[ "$(RELAY_SLEEP=: bash bin/deliver true | tail -1)" = delivered ] || { echo "deliver true"; fail=1; }
RELAY_SLEEP=: bash bin/deliver false >/dev/null; [ $? = 1 ] || { echo "deliver false"; fail=1; }
# ADR-0009: 4 attempts, waits 3, 9, 27 s
[ "$(bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "plan default"; fail=1; }
# runbook key RELAY_ATTEMPTS raises the count, same progression
[ "$(RELAY_ATTEMPTS=6 bash bin/deliver --plan)" = "attempts=6 waits=3,9,27,81,243" ] || { echo "plan RELAY_ATTEMPTS"; fail=1; }
# the removed key is not read (CHANGELOG 1.9.0)
[ "$(RELAY_RETRY_MAX=9 bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "plan RELAY_RETRY_MAX"; fail=1; }
# a failing command really uses 4 attempts and the agreed waits
out=$(RELAY_SLEEP=echo bash bin/deliver false)
[ "$(echo "$out" | grep -c '^attempt ')" = 4 ] && [ "$(echo "$out" | grep '^wait ' | tr '\n' ' ')" = "wait 3s wait 9s wait 27s " ] || { echo "deliver false schedule"; fail=1; }
exit $fail
EOF
echo "red:"; bash tests/deliver_test.sh
f=lib/delivery/retry.sh
sed -i 's/standard exponential backoff\./ADR-0009 (docs\/adr\/0009-webhook-retry-policy.md)./; s/^# Attempts:.*/# Attempts: RELAY_ATTEMPTS (default 4). Wait before attempt i+1 is 3^i s (3, 9, 27)./; s/DEFAULT=3/DEFAULT=4/; s/WAIT_BASE=2/WAIT_BASE=3/; s/WAIT_FIRST=1/WAIT_FIRST=3/; s/RELAY_RETRY_MAX:-/RELAY_ATTEMPTS:-/' $f
sed -i 's/^3 attempts with doubling.*/Superseded by ADR-0009: 4 attempts, waits 3, 9, 27 s. The count can be raised with RELAY_ATTEMPTS (docs\/runbook.md, "Slow endpoints")./; s/^Status: draft\./Status: draft; the Retry section is superseded by ADR-0009./' docs/design/delivery.md
echo green:; bash tests/deliver_test.sh && echo PASS; bash scripts/verify.sh; git diff --stat; sed -n 1,8p CHANGELOG.md >/dev/null
